import{_ as a,o as s,c as t,a5 as i}from"./chunks/framework.DrDMl0tG.js";const r="/assets/rayrai_nested_glass_showcase.CP0uZRia.png",m=JSON.parse('{"title":"Rayrai Example: Nested Glass","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/rayrai/rayrai_nested_glass.md","filePath":"sections/examples/rayrai/rayrai_nested_glass.md"}'),n={name:"sections/examples/rayrai/rayrai_nested_glass.md"};function o(l,e,d,c,p,h){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="rayrai-example-nested-glass" tabindex="-1">Rayrai Example: Nested Glass <a class="header-anchor" href="#rayrai-example-nested-glass" aria-label="Permalink to &quot;Rayrai Example: Nested Glass&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Traces refraction through a water-filled glass with an enclosed air bubble, an empty hollow cup, a concave amber torus, and two overlapping tinted glass solids. The media have explicit indices of refraction and dielectric priorities, so overlapping interfaces resolve in a defined order. The default backend uses Vulkan hardware ray queries when available and otherwise selects the portable OpenGL tracer. It starts with 10 paths per frame and at most 10 bounces.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p><img src="'+r+`" alt="Nested water, glass, and air with overlapping transparent solids"></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>rayrai_nested_glass</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_nested_glass</span></span></code></pre></div><p>On Windows, run <code>rayrai_nested_glass.exe</code> instead. This example renders in process with rayrai and does not need <code>rayrai_tcp_viewer</code>. Drag to look, use WASD and Space to move, and click an object to orbit it. The <strong>Geometry refraction</strong> panel controls the backend, samples per frame, and bounce count.</p><p>For a finite PNG capture or a stacked-media stress scene:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_nested_glass</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --backend=portable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out=nested_glass.png</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frames=24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --warmup=0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_nested_glass</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --layers=4</span></span></code></pre></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><ul><li><code>--backend=auto|portable|vulkan</code> selects the tracing backend; <code>vulkan</code> requires the Vulkan ray-query path.</li><li><code>--samples=N</code> (1 to 64) and <code>--bounces=N</code> (1 to 128) set the paths per frame and the bounce limit.</li><li><code>--layers=N</code> builds 1 to 16 concentric glass/water boxes; <code>--layers=0</code> returns to the default composition.</li><li><code>--out=FILE</code> renders <code>--frames</code> frames (after <code>--warmup</code> frames) in a hidden window, saves a PNG, and exits. <code>--benchmark</code> runs a finite timing pass instead; <code>--width</code>, <code>--height</code>, and <code>--msaa</code> set the render size and MSAA level.</li></ul>`,15)])])}const g=a(n,[["render",o]]);export{m as __pageData,g as default};
